  async function toggleWishlist(restaurant: Restaurant, profileId = profile?.id) { if (!profileId) return; const old = await db.wishlists.where('[restaurantId+profileId]').equals([restaurant.id, profileId]).first(); if (old) await db.wishlists.put({ ...old, isActive: !old.isActive, updatedAt: new Date().toISOString(), ...newRevision(old.revisionId) }); else { const now = new Date().toISOString(); await db.wishlists.add({ id: id(), restaurantId: restaurant.id, profileId, isActive: true, createdAt: now, updatedAt: now, createdByProfileId: profileId, ...newRevision() }); } await refresh(); }
