  async function saveCatalogOption(e:FormEvent<HTMLFormElement>) { e.preventDefault();if(!profile)return;const label=optionLabel.trim();const min=optionKind==='budget'&&optionMin!==''?Number(optionMin):undefined;const max=optionKind==='budget'&&optionMax!==''?Number(optionMax):undefined;if(!label){setNotice('請輸入選項名稱。');return;}if(optionKind==='budget'&&(min===undefined&&max===undefined||min!==undefined&&max!==undefined&&min>max)){setNotice('預算請至少設定一個界線，且上限不可低於下限。');return;}if(catalogOptions.some(option=>!option.deletedAt&&option.kind===optionKind&&option.id!==optionEditing?.id&&option.label.trim().toLocaleLowerCase()===label.toLocaleLowerCase()&&(optionKind!=='budget'||option.budgetMin===min&&option.budgetMax===max))){setNotice('已有相同選項。');return;}setOptionBusy(true);try{if(optionEditing)await updateEntity(db.catalogOptions,optionEditing,{label,budgetMin:min,budgetMax:max});else{const now=new Date().toISOString();await db.catalogOptions.add({id:id(),kind:optionKind,label,budgetMin:min,budgetMax:max,createdAt:now,updatedAt:now,createdByProfileId:profile.id,...newRevision()});}resetCatalogEditor();await refresh();}catch(error){setNotice(error instanceof Error?error.message:'選項儲存失敗。');}finally{setOptionBusy(false);}}
  async function deleteCatalogOption(option:CatalogOption) {
    const deleting = option.kind==='category'&&!option.parentOptionId ? [option,...catalogOptions.filter(item=>item.kind==='category'&&item.parentOptionId===option.id&&!item.deletedAt)] : [option];
    const deletingIds=new Set(deleting.map(item=>item.id));
    const affected=restaurants.filter(restaurant => option.kind==='category'
      ? Boolean((restaurant.categoryOptionIds??[]).some(categoryId=>deletingIds.has(categoryId)) || deleting.some(item=>restaurant.categoryTags?.includes(categoryPath(item,catalogOptions))))
      : option.kind==='customTag'
        ? Boolean(restaurant.customTagOptionIds?.includes(option.id) || restaurant.customTags?.includes(option.label))
        : option.kind==='location'
          ? restaurant.locationOptionId===option.id || restaurant.locationText===option.label
          : restaurant.budgetOptionId===option.id || (restaurant.budgetMin===option.budgetMin && restaurant.budgetMax===option.budgetMax));
    const affectedText=affected.length?affected.map(restaurant=>`・${restaurant.name}`).join('\n'):'（沒有餐廳使用此選項）';const labels=deleting.map(item=>categoryPath(item,catalogOptions));const description=deleting.length>1?`大類「${option.label}」及其 ${deleting.length-1} 個子類`: `「${option.label}」`;
    if(!confirm(`即將刪除${description}。以下餐廳會同步移除相關料理類型：\n\n${affectedText}\n\n是否繼續？`))return;
    if(!confirm(`再次確認：永久刪除${description}，並從上述餐廳移除相關資料？此動作會同步到另一台裝置。`))return;
    const deletionIds = await deletionIdsFor(deleting);
    await db.transaction('rw',db.catalogOptions,db.restaurants,db.settings,async()=>{
      for(const restaurant of affected){
        const categoryIds=restaurant.categoryOptionIds??[]; const categoryIndexes=new Set(categoryIds.map((id,index)=>deletingIds.has(id)?index:-1).filter(index=>index>=0));
        const customIds=restaurant.customTagOptionIds??[]; const customIndexes=new Set(customIds.map((id,index)=>id===option.id?index:-1).filter(index=>index>=0));
        const changes:Partial<Restaurant>={};
        if(option.kind==='category') restaurant.categoryTags.forEach((tag,index)=>{if(labels.includes(tag)||deleting.some(item=>item.label===tag))categoryIndexes.add(index);});
        if(option.kind==='customTag') (restaurant.customTags??[]).forEach((label,index)=>{if(label===option.label)customIndexes.add(index);});
        if(categoryIndexes.size){changes.categoryOptionIds=categoryIds.filter((_,index)=>!categoryIndexes.has(index));changes.categoryTags=restaurant.categoryTags.filter((_,index)=>!categoryIndexes.has(index));}
        if(customIndexes.size){changes.customTagOptionIds=customIds.filter((_,index)=>!customIndexes.has(index));changes.customTags=(restaurant.customTags??[]).filter((_,index)=>!customIndexes.has(index));}
        if(option.kind==='location'&&(restaurant.locationOptionId===option.id||restaurant.locationText===option.label)){changes.locationOptionId=undefined;changes.locationText='';}
        if(option.kind==='budget'&&(restaurant.budgetOptionId===option.id||restaurant.budgetMin===option.budgetMin&&restaurant.budgetMax===option.budgetMax)){changes.budgetOptionId=undefined;changes.budgetMin=undefined;changes.budgetMax=undefined;}
        if(Object.keys(changes).length)await updateEntity(db.restaurants,restaurant,changes);
      }
      await purgeOptionIds(deletionIds);
    });
    if (optionEditing?.id === option.id) resetCatalogEditor();
    if (option.kind === 'category') {
      if(deletingIds.has(atlasCategoryParent)){setAtlasCategoryParent('');setAtlasCategoryChildren([]);}else setAtlasCategoryChildren(current=>current.filter(categoryId=>!deletingIds.has(categoryId)));
      setPickerCategories(current => current.filter(categoryId => !deletingIds.has(categoryId)));
    }
    if (option.kind === 'location' && pickerLocation === option.label) setPickerLocation('');
    if (option.kind === 'budget' && budget === option.id) setBudget('');
    await refresh(); setNotice(`選項「${option.label}」已刪除。`);
  }
  function editRestaurant(r?: Restaurant) { setEditing(r ?? null); setCoverFile(undefined); setDraft(r ? { name:r.name, categoryOptionIds:r.categoryOptionIds??restaurantCategories(r,catalogOptions).map(label=>catalogOptions.find(option=>option.kind==='category'&&option.label===label)?.id).filter((value):value is string=>Boolean(value)), customTagOptionIds:r.customTagOptionIds??(r.customTags??[]).map(label=>catalogOptions.find(option=>option.kind==='customTag'&&option.label===label)?.id).filter((value):value is string=>Boolean(value)), locationOptionId:r.locationOptionId??catalogOptions.find(option=>option.kind==='location'&&option.label===r.locationText)?.id??'', budgetOptionId:r.budgetOptionId??catalogOptions.find(option=>option.kind==='budget'&&option.budgetMin===r.budgetMin&&option.budgetMax===r.budgetMax)?.id??'', mapUrl:r.mapUrl ?? '', memo:r.memo ?? '', coverAssetId:r.coverAssetId } : blank); }
