  async function addPost(e: FormEvent<HTMLFormElement>) { e.preventDefault(); if (!detail || !profile) return; const form = e.currentTarget; const data = new FormData(form); const body = String(data.get('body') ?? '').trim(); if (!body) return; const files = data.getAll('photos').filter(x => x instanceof File && x.size > 0) as File[]; if (files.length > 5) { setNotice('每篇文章最多附 5 張照片。'); return; } setBusy(true); try { const assets = await Promise.all(files.map(processPhoto)); const now = new Date().toISOString(); await db.posts.add({ id:id(), restaurantId:detail.id, body, photoAssetIds:assets.map(a=>a.id), isPinned:false, createdAt:now, updatedAt:now, createdByProfileId:profile.id, ...newRevision() }); await refresh(); form.reset();setPostFiles([]); } catch (error) { setNotice(error instanceof Error ? error.message : '照片處理失敗'); } finally { setBusy(false); } }
  async function togglePin(post: RestaurantPost) { const pinned = posts.filter(p=>p.restaurantId===post.restaurantId&&p.isPinned&&!p.deletedAt).length; if (!post.isPinned && pinned>=3) { setNotice('這間店已有 3 篇置頂文章，請先取消其他文章置頂。'); return; } await db.posts.put({ ...post, isPinned:!post.isPinned, updatedAt:new Date().toISOString(), ...newRevision(post.revisionId) }); await refresh(); }
